// features/lifecycle.feature: A certificate that expires today can still be approved
import { mkdirSync, writeFileSync } from "node:fs";
import path from "node:path";

import { SAMPLES, } from "../../fixtures/factory";
import { expect, expectStatus, test } from "../../fixtures";

test("a certificate that expires today can still be approved", { tag: "@LIF-07" }, async ({ factory, apiAs }, testInfo) => {
  // Arrange: an insurance certificate expiring today, in the ISO format extraction parses
  const today = new Date().toISOString().slice(0, 10);
  const certificate = testInfo.outputPath("insurance_certificate_expires_today.txt");
  mkdirSync(path.dirname(certificate), { recursive: true });
  writeFileSync(
    certificate,
    `Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: $2,000,000\nExpiry Date: ${today}\n`,
  );
  const { extractions } = await factory.vendorInReview({
    files: { insurance_certificate: path.relative(SAMPLES, certificate) },
  });
  const reviewer = await apiAs("reviewer");

  // Act
  const response = await reviewer.post(`/api/extractions/${extractions.insurance_certificate.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert
  const decided = await expectStatus(response, 200);
  expect(decided.status).toBe("approved");
  const stored = await factory.extraction(decided.document_id, "reviewer");
  expect(stored.status).toBe("approved");
});
